import {copy,KEYS,noteName} from './music.js';
import {PHRASE_DEFAULTS,planPhraseTransform} from './phrase-transform.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bar=n=>+(n/4+1).toFixed(4),keyName=k=>k.replace('minor','小调').replace('major','大调');
export function createPhraseTransformUI({getProject,getRevision,getSelection,commit,protectedChange,modal,toast}){
 let flow=0;
 return function showPhraseTransform(){
  const before=copy(getProject()),selection=copy(getSelection()),at=getRevision(),t=before.tracks.find(t=>t.id===selection.trackId),clip=t?.clips.find(c=>c.id===selection.clipId);
  if(!clip)return toast('请先选择一个音块');const ticket=++flow;let result=null,page=0,busy=false;
  const d=modal('乐句变换 · 只改当前块',`<div class="phrase-transform-form"><p><strong>${escape(t.name)} · ${escape(clip.name)}</strong> · 第 ${bar(clip.start)} 小节。先预览，再一次应用。不生成、不调用模型、不播放。</p><div class="phrase-presets">${[['half','紧凑一半','时间与块长 ×½'],['double','展开两倍','时间与块长 ×2'],['reverse','乐句倒序','镜像音符区间'],...(t.kind==='tonal'?[['octave','高一个八度','音高 +12 半音'],['scale','贴合工程调性','最近调内音，不改全局']]:[])].map(([id,name,hint])=>`<button class="quiet" data-phrase-preset="${id}"><strong>${name}</strong><small>${hint}</small></button>`).join('')}</div><div class="phrase-fields"><label>节奏与音块长度<select id="phrase-ratio"><option value="0.5">×½ · 紧凑一半</option><option value="1" selected>×1 · 保持</option><option value="2">×2 · 展开两倍</option></select></label><label>音高移动（半音）<input id="phrase-transpose" type="number" min="-24" max="24" step="1" value="0" ${t.kind==='drum'?'disabled':''}></label></div><label class="check-label"><input id="phrase-reverse" type="checkbox">倒序整块音符区间（不是音频倒放）</label><label class="modal-label" for="phrase-scale">移调后，吸附到最近调内音</label><select id="phrase-scale" ${t.kind==='drum'?'disabled':''}><option value="keep">不吸附，保留半音间距</option>${Object.keys(KEYS).map(k=>`<option value="${k}">${keyName(k)}${k===before.key?' · 当前工程':''}</option>`).join('')}</select><label class="modal-label" for="phrase-timing">原音符的微偏移</label><select id="phrase-timing"><option value="follow">随节奏倍数与倒序方向变换</option><option value="keep">保留原拍数与方向（越界仍拒绝）</option><option value="clear">清除微偏移，保留全局摇摆</option></select><label class="check-label"><input id="phrase-extend" type="checkbox">需要时空白延长工程（最多 64 小节）</label><div id="phrase-summary" class="performance-summary" aria-live="polite"></div><div id="phrase-changes"></div><div id="phrase-error" role="status" class="export-progress"></div><div class="modal-notice">起点不移动；节奏倍数同时缩放块长、相对起点与音符长度，紧凑后释放的区域留空，变长不得碰到任何旧块。倒序为块长 − 旧相对起点 − 旧长度；不同长度和弦可能不再同起音。调内吸附就近、等距离选较低音，可合并原来不同音高，不是和声重写或源调性分析。鼓不变音高。保留音符数 / IDs / 力度、块静音、源库、其他块、混音与全局速度 / 调性 / 摇摆；变化的共享块只独立化此块。全局摇摆仍在新名义网格上应用，实际时间不一定严格倍乘或镜像。音高 / 时长 / 微偏移 / 碰撞超限整块拒绝，不自动删音符。先备份再应用，可一次撤销；预设替换草稿，不自动应用。</div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="phrase-apply">备份并应用变换</button>');
  const root=$('.phrase-transform-form');d.addEventListener('close',()=>{if(ticket===flow)++flow},{once:true});
  const revisionGuard=()=>{const now=getSelection();if(at!==getRevision()||now.trackId!==selection.trackId||now.clipId!==selection.clipId)throw Error('工程或音块选择已改变，请重新打开乐句变换。')};
  const guard=()=>{revisionGuard();if(ticket!==flow||!root.isConnected||!d.open)throw Error('窗口已改变，没有应用旧乐句变换。')};
  const read=()=>{guard();return planPhraseTransform(before,t.id,clip.id,{controls:{ratio:+$('#phrase-ratio').value,reverse:$('#phrase-reverse').checked,transpose:$('#phrase-transpose').value===''?NaN:+$('#phrase-transpose').value,scale:$('#phrase-scale').value,timing:$('#phrase-timing').value,extend:$('#phrase-extend').checked}})};
  function rows(){const list=result?.changes||[],pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages-1);$('#phrase-changes').innerHTML=list.length?`<details class="performance-table" open><summary>逐音前后 · ${list.length} 个有变化</summary><div class="performance-table-scroll"><table><thead><tr><th>音高</th><th>名义小节</th><th>长度（拍）</th><th>微偏移（拍）</th><th>实际起音变化</th></tr></thead><tbody>${list.slice(page*12,page*12+12).map(x=>`<tr><th>${noteName(x.before.pitch)} → ${noteName(x.after.pitch)}</th><td>${bar(x.before.start)} → ${bar(x.after.start)}</td><td>${x.before.duration} → ${x.after.duration}</td><td>${x.before.timingOffset||0} → ${x.after.timingOffset||0}</td><td>${((x.beatAfter-x.beatBefore)*60000/before.bpm).toFixed(2)} ms</td></tr>`).join('')}</tbody></table></div><div class="performance-pagination"><button class="quiet compact" id="phrase-prev" ${page===0?'disabled':''}>上一页</button><span>${page+1} / ${pages} 页</span><button class="quiet compact" id="phrase-next" ${page===pages-1?'disabled':''}>下一页</button></div></details>`:'';if($('#phrase-prev'))$('#phrase-prev').onclick=()=>{if(!busy){page--;rows()}};if($('#phrase-next'))$('#phrase-next').onclick=()=>{if(!busy){page++;rows()}}}
  function update(){result=null;try{result=read();const r=result.report;page=0;$('#phrase-summary').innerHTML=`<span class="eyebrow">静音预览 · 尚未应用</span><h3>${r.targetNotes} 音符 · ${r.changedNotes} 个改变</h3><p>块长 ${clip.length/4} → ${result.clipAfter.length/4} 小节；起点第 ${bar(clip.start)} 小节不变。<br>音高 ${r.pitchChanged} · 起点 ${r.moved} · 长度 ${r.durationChanged} · 微偏移 ${r.timingChanged}。</p>${r.barsAfter!==r.barsBefore?`<p>工程 ${r.barsBefore} → ${r.barsAfter} 小节，仅空白延长；标签与练习范围不动。</p>`:''}${r.detached?'<p class="pattern-local-notice">↔ 只独立化当前共享块，源与其他引用保持。</p>':''}<p>同音高重叠 ${r.overlapsBefore.count} → ${r.overlapsAfter.count} 对，仅提示，不删音符。${r.snapped?`${r.snapped} 个音符被调内吸附。`:''}</p>`;$('#phrase-error').textContent=r.changed?'':'草稿没有变化，当前音乐保持。';$('#phrase-apply').disabled=!r.changed||busy;rows()}catch(e){$('#phrase-summary').textContent='没有应用任何内容，请调整变换参数。';$('#phrase-error').textContent=e.message;$('#phrase-apply').disabled=true;$('#phrase-changes').innerHTML=''}}
  for(const id of ['ratio','scale','timing','reverse','extend'])$('#phrase-'+id).onchange=()=>{if(!busy)update()};$('#phrase-transpose').oninput=()=>{if(!busy)update()};
  root.querySelectorAll('[data-phrase-preset]').forEach(button=>button.onclick=()=>{if(busy)return;const preset=button.dataset.phrasePreset;$('#phrase-ratio').value=preset==='half'?'0.5':preset==='double'?'2':'1';$('#phrase-transpose').value=preset==='octave'?12:0;$('#phrase-reverse').checked=preset==='reverse';$('#phrase-scale').value=preset==='scale'?before.key:'keep';$('#phrase-timing').value=PHRASE_DEFAULTS.timing;$('#phrase-extend').checked=false;update()});
  $('#phrase-apply').onclick=async()=>{try{guard();if(!result?.report.changed||busy)throw Error('请先得到有变化的合法预览');const planned=result;busy=true;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=true);$('#phrase-apply').disabled=true;$('#phrase-error').textContent='正在保存变换前版本，工程尚未改变…';let applied=false;
   await protectedChange(({fallback=false}={})=>{try{fallback?revisionGuard():guard();if(commit(planned.project)){applied=true;d.close();toast(`已变换当前块 · ${planned.report.changedNotes} 个音符，可一次撤销。${planned.report.detached?'源与其他引用保持。':''}`)}}catch(e){toast(e.message)}},'乐句变换前 · '+clip.name);
   if(!applied&&root.isConnected&&d.open){busy=false;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=false);if(t.kind==='drum'){$('#phrase-transpose').disabled=true;$('#phrase-scale').disabled=true}update()}
  }catch(e){if(root.isConnected){$('#phrase-error').textContent=e.message;$('#phrase-apply').disabled=true}else toast(e.message)}};update();
 };
}
